};

struct line {
  double A, B, C;
  line(point a, point b) {
    A = a.y - b.y;
    B = b.x - a.x;
    C = -A * a.x - B * a.y;
  }
};

struct seg {
  point p, q;
  seg(point p, point q) : p(p), q(q) {}
};

double gd() {
  double x;
  scanf("%lf", &x);
  return x;
}

bool linesIntersect(line a, line b) {
  return fabs(a.A * b.B - b.A * a.B) > eps;
}

double dist(line a, point p) {
  return (a.A * p.x + a.B * p.y + a.C) / hypot(a.A, a.B);
}

double dist(seg a, point p) {
  return dist(line(a.p, a.q), p);
}

point intersectLines(line a, line b) {
  double det = a.A * b.B - b.A * a.B;
  double x = -(a.C * b.B - a.B * b.C) / det;
  double y = -(a.A * b.C - a.C * b.A) / det;
  return point(x, y);
}

bool inRange(double value, double left, double right) {
  return min(left, right) - eps <= value &&
         value <= max(left, right) + eps;
}

bool intersect(seg a, seg b, bool allowCollision = false) {
  line la(a.p, a.q);
  line lb(b.p, b.q);

  if (max(min(a.p.x, a.q.x), min(b.p.x, b.q.x)) >
      min(max(a.p.x, a.q.x), max(b.p.x, b.q.x)) + eps) {
    return false;
  }

  if (max(min(a.p.y, a.q.y), min(b.p.y, b.q.y)) >
      min(max(a.p.y, a.q.y), max(b.p.y, b.q.y)) + eps) {
    return false;
  }

  if (linesIntersect(la, lb)) {
    point c = intersectLines(la, lb);
    return inRange(c.x, a.p.x, a.q.x) &&
           inRange(c.y, a.p.y, a.q.y) &&
           inRange(c.x, b.p.x, b.q.x) &&
           inRange(c.y, b.p.y, b.q.y);
  }

  if (fabs(dist(la, b.p)) < eps) {
    return !allowCollision;
  }

  return false;
}

