  return min(s.p.x, s.q.x) - eps <= p.x &&
         p.x <= max(s.p.x, s.q.x) + eps &&
         min(s.p.y, s.q.y) - eps <= p.y &&
         p.y <= max(s.p.y, s.q.y) + eps;
